{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "In vivo biodistribution in mice showed very low initial brain uptake of a radiolabeled benzamide, supporting inadequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "In non-human primates, sacubitril showed low CSF and brain concentrations with CSF:plasma ≤0.0044 and brain:plasma ≤0.0326, indicating poor CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Practolol was detected in brain tissue, but at levels 40-fold lower than propranolol, providing only weak evidence of meaningful CNS access.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple direct in-vivo records across species show very low brain or CSF uptake, with the only positive record showing low relative brain detection. The overall evidence supports inadequate CNS access.",
  "evidence_gaps": [
    "The only positive record is relative and does not establish whether brain levels are sufficient for a pharmacological effect.",
    "Several negative records are based on PET-tracer suitability, which may be a stricter threshold than meaningful CNS access."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

